namespace ITDigitacao.Legacy.App {
 internal static class Program { [STAThread] private static void Main(){ new Application().Run(new MainWindow()); } }
 internal sealed class MainWindow:Window {
  readonly string root=AppDomain.CurrentDomain.BaseDirectory; ActivityRepository repo; SessionManager session; StackPanel page; TextBox query,entry; ComboBox diff; TextBlock stats,clock,resultCount; WrapPanel categoryCards; string selectedCategoryId; DispatcherTimer timer;
  static readonly Brush Red=new SolidColorBrush(Color.FromRgb(217,0,0)), Ink=new SolidColorBrush(Color.FromRgb(23,23,23));
  public MainWindow(){Title="IT Digitação • Instituto de Transformação";Width=1060;Height=720;MinWidth=390;MinHeight=340;WindowStartupLocation=WindowStartupLocation.CenterScreen;Background=new SolidColorBrush(Color.FromRgb(244,246,249));
   try{using(FileStream s=File.OpenRead(Path.Combine(root,"atividades.json")))repo=ActivityRepository.Load(s);}catch(Exception e){MessageBox.Show("Falha ao carregar catálogo: "+e.Message);}
   DockPanel shell=new DockPanel(); Border header=new Border{Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(226,229,234)),BorderThickness=new Thickness(0,0,0,1)};DockPanel.SetDock(header,Dock.Top);
   StackPanel headerContent=new StackPanel{Margin=new Thickness(20,8,20,5)};Grid brandRow=new Grid{MinHeight=58};brandRow.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});brandRow.ColumnDefinitions.Add(new ColumnDefinition());brandRow.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});
   Image logo=Pic("Assets/logo-it-digitacao.png",46);logo.Margin=new Thickness(0,0,10,0);logo.VerticalAlignment=VerticalAlignment.Center;Grid.SetColumn(logo,0);brandRow.Children.Add(logo);
   StackPanel identity=new StackPanel{VerticalAlignment=VerticalAlignment.Center};identity.Children.Add(T("IT Digitação",23,true,Ink));identity.Children.Add(T("Instituto de Transformação",12,false,new SolidColorBrush(Color.FromRgb(84,92,105))));Grid.SetColumn(identity,1);brandRow.Children.Add(identity);
   StackPanel actions=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center};actions.Children.Add(B("Configurações",Settings,false));actions.Children.Add(B("Sair",delegate{Close();},false));Grid.SetColumn(actions,2);brandRow.Children.Add(actions);headerContent.Children.Add(brandRow);
   WrapPanel nav=new WrapPanel{Margin=new Thickness(0,2,0,0)};Nav(nav,"Início",Home);Nav(nav,"Biblioteca",Library);Nav(nav,"Como digitar",Guide);Nav(nav,"Configurações",Settings);headerContent.Children.Add(nav);header.Child=headerContent;shell.Children.Add(header);
   Border footer=new Border{Background=new SolidColorBrush(Color.FromRgb(166,0,0)),Padding=new Thickness(20,5,20,5)};DockPanel.SetDock(footer,Dock.Bottom);Grid footGrid=new Grid();footGrid.ColumnDefinitions.Add(new ColumnDefinition());footGrid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});StackPanel institute=new StackPanel{Orientation=Orientation.Horizontal};institute.Children.Add(Pic("Assets/logo-instituto.png",24));institute.Children.Add(T("Instituto de Transformação",12,true,Brushes.White));footGrid.Children.Add(institute);StackPanel status=new StackPanel{Orientation=Orientation.Horizontal};status.Children.Add(T("● Offline  •  v2.0.0-beta.2 Legacy",12,false,Brushes.White));Grid.SetColumn(status,1);footGrid.Children.Add(status);footer.Child=footGrid;shell.Children.Add(footer);
   ScrollViewer scroll=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};page=new StackPanel{Margin=new Thickness(20,18,20,12),MaxWidth=1150,HorizontalAlignment=HorizontalAlignment.Center};scroll.Content=page;shell.Children.Add(scroll);Content=shell;Home();timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};timer.Tick+=delegate{if(session!=null){session.Tick();if(session.Finished)Results();if(clock!=null)clock.Text="Restante "+FormatRemaining(session.Remaining);}};timer.Start(); }
  TextBlock T(string s,double n,bool bold,Brush brush=null){return new TextBlock{Text=s,FontSize=n,FontWeight=bold?FontWeights.Bold:FontWeights.Normal,Foreground=brush??Ink,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(6)};}
  Button B(string s,Action a,bool primary=true){Button b=new Button{Content=s,Padding=new Thickness(14,9,14,9),Margin=new Thickness(5),Background=primary?Red:Brushes.White,Foreground=primary?Brushes.White:Ink,BorderBrush=Red};b.Click+=delegate{a();};return b;}
  void Nav(Panel p,string s,Action a){p.Children.Add(B(s,a,false));} void Reset(string h,string sub){page.Children.Clear();page.Children.Add(T(h,29,true));page.Children.Add(T(sub,15,false));}
  void Home(){page.Children.Clear();Border hero=new Border{Background=new LinearGradientBrush(Color.FromRgb(166,0,0),Color.FromRgb(217,0,0),45),CornerRadius=new CornerRadius(16),Padding=new Thickness(28),Margin=new Thickness(0,0,0,18)};Grid heroGrid=new Grid{MinHeight=210};heroGrid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(3,GridUnitType.Star)});heroGrid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(2,GridUnitType.Star)});StackPanel copy=new StackPanel{VerticalAlignment=VerticalAlignment.Center,MaxWidth=480};copy.Children.Add(T("Aprenda. Pratique. Transforme.",13,true,new SolidColorBrush(Color.FromRgb(255,241,242))));copy.Children.Add(T("Vamos aprender algo incrível hoje?",34,true,Brushes.White));copy.Children.Add(T("Descubra novos conhecimentos enquanto desenvolve suas habilidades no teclado.",15,false,Brushes.White));Grid.SetColumn(copy,0);heroGrid.Children.Add(copy);Image mascot=Pic("Assets/mascote-boas-vindas.png",205);mascot.HorizontalAlignment=HorizontalAlignment.Center;mascot.VerticalAlignment=VerticalAlignment.Bottom;Grid.SetColumn(mascot,1);heroGrid.Children.Add(mascot);hero.Child=heroGrid;page.Children.Add(hero);
   page.Children.Add(T("◷  Escolha seu tempo de prática",21,true));page.Children.Add(T("Quanto tempo você tem disponível hoje?",13,false,new SolidColorBrush(Color.FromRgb(84,92,105))));UniformGrid durations=new UniformGrid{Columns=6,Margin=new Thickness(-5,4,-5,8)};foreach(int minutes in new int[]{5,10,15,20,25,30}){RadioButton option=new RadioButton{GroupName="PracticeDuration",IsChecked=minutes==10,Margin=new Thickness(5),Padding=new Thickness(8),MinHeight=88,Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(226,229,234)),BorderThickness=new Thickness(1),Content=new StackPanel{Children={T("◷",18,true,Red),T(minutes.ToString(),27,true),T("minutos",12,false,new SolidColorBrush(Color.FromRgb(84,92,105)))}}};durations.Children.Add(option);}page.Children.Add(durations);
   page.Children.Add(B("▶  Começar minha aventura",delegate{RadioButton selected=durations.Children.OfType<RadioButton>().FirstOrDefault(x=>x.IsChecked==true);int minutes=selected==null?10:int.Parse(((StackPanel)selected.Content).Children.OfType<TextBlock>().ElementAt(1).Text);session=new SessionManager(minutes,new SessionClock());Library();},true));
   Grid benefits=new Grid{Margin=new Thickness(-5,8,-5,0)};benefits.ColumnDefinitions.Add(new ColumnDefinition());benefits.ColumnDefinitions.Add(new ColumnDefinition());benefits.ColumnDefinitions.Add(new ColumnDefinition());string[] heads={"Aprenda brincando","Acompanhe seu progresso","Desenvolva sua confiança"};string[] desc={"Conheça temas educativos enquanto pratica.","Veja precisão, velocidade e evolução.","Pratique no seu ritmo, todos os dias."};for(int i=0;i<3;i++){Border card=new Border{Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(226,229,234)),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(12),Padding=new Thickness(15),Margin=new Thickness(5)};StackPanel stack=new StackPanel();stack.Children.Add(T(new string[]{"✦","↗","✓"}[i],23,true,Red));stack.Children.Add(T(heads[i],15,true));stack.Children.Add(T(desc[i],13,false));card.Child=stack;Grid.SetColumn(card,i);benefits.Children.Add(card);}page.Children.Add(benefits);}
  Image Pic(string f,double h){Image i=new Image{Height=h,HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(5)};string p=Path.Combine(root,f);if(File.Exists(p))i.Source=new BitmapImage(new Uri(p));return i;}
  void Library(){page.Children.Clear();if(repo==null){Reset("Biblioteca educativa","Catálogo indisponível.");return;}Border hero=new Border{Background=new LinearGradientBrush(Color.FromRgb(166,0,0),Color.FromRgb(217,0,0),45),CornerRadius=new CornerRadius(15),Padding=new Thickness(24),Margin=new Thickness(0,0,0,14)};Grid hg=new Grid();hg.ColumnDefinitions.Add(new ColumnDefinition());hg.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});StackPanel ht=new StackPanel{VerticalAlignment=VerticalAlignment.Center};ht.Children.Add(T("Biblioteca educativa",28,true,Brushes.White));ht.Children.Add(T("Descubra novos assuntos enquanto pratica digitação.",14,false,Brushes.White));ht.Children.Add(T(repo.Categories.Count+" categorias • "+repo.Activities.Count+" atividades",13,true,Brushes.White));hg.Children.Add(ht);Image teach=Pic("Assets/mascote-ensinando.png",130);Grid.SetColumn(teach,1);hg.Children.Add(teach);hero.Child=hg;page.Children.Add(hero);
   categoryCards=new WrapPanel{Margin=new Thickness(-5,0,-5,8)};foreach(Category category in repo.Categories){Border card=new Border{Width=205,MinHeight=215,Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(226,229,234)),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(13),Margin=new Thickness(5),Padding=new Thickness(11),Cursor=System.Windows.Input.Cursors.Hand};StackPanel body=new StackPanel();Image art=Pic("Assets/Categorias/"+category.Id+".png",92);art.HorizontalAlignment=HorizontalAlignment.Center;body.Children.Add(art);body.Children.Add(T(category.Name,16,true));body.Children.Add(T(category.Description,12,false,new SolidColorBrush(Color.FromRgb(84,92,105))));body.Children.Add(T(repo.Activities.Count(x=>x.CategoryId==category.Id)+" atividades",12,true,Red));card.Child=body;card.MouseLeftButtonUp+=delegate{selectedCategoryId=category.Id;Render();};categoryCards.Children.Add(card);}page.Children.Add(categoryCards);
   StackPanel filters=new StackPanel{Orientation=Orientation.Horizontal};query=new TextBox{Width=310,Padding=new Thickness(12,7,12,7),MinHeight=40,FontSize=14,Margin=new Thickness(4),ToolTip="Pesquisar atividades"};diff=new ComboBox{Width=175,Padding=new Thickness(8),Margin=new Thickness(4),ItemsSource=new string[]{"Todas","Iniciante","Intermediário","Avançado"},SelectedIndex=0,FontSize=14};filters.Children.Add(query);filters.Children.Add(diff);filters.Children.Add(B("Pesquisar",Render));filters.Children.Add(B("Limpar",delegate{query.Text="";diff.SelectedIndex=0;selectedCategoryId=null;Render();},false));page.Children.Add(filters);resultCount=T("",13,false);page.Children.Add(resultCount);Render();}
  void Render(){if(repo==null||query==null)return;string d=diff.SelectedIndex>0?(string)diff.SelectedItem:null;var acts=repo.Find(query.Text,d,selectedCategoryId);resultCount.Text=acts.Count+" atividades encontradas"+(selectedCategoryId==null?"":" • "+repo.Categories.First(c=>c.Id==selectedCategoryId).Name);for(int i=page.Children.Count-1;i>=4;i--)page.Children.RemoveAt(i);foreach(Activity a in acts){Border card=new Border{Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(226,229,234)),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(13),Padding=new Thickness(16),Margin=new Thickness(5)};StackPanel row=new StackPanel();row.Children.Add(T(a.Difficulty.ToUpper(),11,true,Red));row.Children.Add(T(a.Title,18,true));row.Children.Add(T(a.Description,14,false));row.Children.Add(T(a.EstimatedMinutes+" min • "+a.WordCount+" palavras",12,false,new SolidColorBrush(Color.FromRgb(84,92,105))));row.Children.Add(B("Praticar",delegate{session=session??new SessionManager(10,new SessionClock());session.Open(a);Practice();}));card.Child=row;page.Children.Add(card);}if(acts.Count==0)page.Children.Add(T("Nenhuma atividade encontrada. Limpe os filtros ou tente outra busca.",16,true));}
  void Practice(){Activity a=session.Activity;Reset(a.Title,"Digite o texto, incluindo espaços e acentos.");page.Children.Add(T(a.Text,18,true));entry=new TextBox{AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=130,FontSize=18,Padding=new Thickness(10)};entry.TextChanged+=delegate{session.Apply(entry.Text);};page.Children.Add(entry);clock=T("Restante "+FormatRemaining(session.Remaining),19,true);page.Children.Add(clock);stats=T("Métricas atualizadas ao digitar",14,false);page.Children.Add(stats);entry.TextChanged+=delegate{if(session.Engine!=null)stats.Text="Progresso "+session.Engine.Progress.ToString("0")+"% • Erros "+session.TotalErrors+" • Precisão "+(session.Accuracy.HasValue?session.Accuracy.Value.ToString("0.#")+"%":"—")+" • "+(session.WordsPerMinute.HasValue?session.WordsPerMinute.Value.ToString("0.#")+" ppm":"—");};page.Children.Add(B("Encerrar atividade",Results));page.Children.Add(B("Biblioteca",Library,false));}
  static string FormatRemaining(TimeSpan value){if(value<TimeSpan.Zero)value=TimeSpan.Zero;return string.Format("{0:00}:{1:00}",(int)Math.Floor(value.TotalMinutes),value.Seconds);}
  void Results(){Reset("Resumo da prática","Continue praticando para conquistar novas metas.");page.Children.Add(Pic("Assets/mascote-celebrando.png",150));if(session!=null){page.Children.Add(T("Atividades concluídas: "+session.CompletedCount,18,true));page.Children.Add(T("Precisão "+(session.Accuracy.HasValue?session.Accuracy.Value.ToString("0.#")+"%":"—")+" • Erros "+session.TotalErrors+" • Corrigidos "+session.CorrectedErrors+" • Velocidade "+(session.WordsPerMinute.HasValue?session.WordsPerMinute.Value.ToString("0.#")+" ppm":"—"),15,false));page.Children.Add(T("Estrelas: "+SessionAwards.Stars(session.Evaluated,session.Accuracy),18,true));}clock=null;page.Children.Add(B("Voltar à biblioteca",Library));page.Children.Add(B("Início",Home,false));}
  void Guide(){Reset("Guia ABNT2","Posição inicial: ASDF JKLÇ. Polegares na barra de espaço.");page.Children.Add(Pic("Assets/mascote-ensinando.png",170));page.Children.Add(T("Mão esquerda: mindinho A, anelar S, médio D, indicador F. Mão direita: indicador J, médio K, anelar L, mindinho Ç.",17,false));page.Children.Add(B("Exercitar posição inicial",delegate{Activity a=Activity.HomeRowExercise();session=session??new SessionManager(10,new SessionClock());session.Open(a);Practice();}));}
  void Settings(){Reset("Configurações","Preferências desta instalação local.");page.Children.Add(T("Tamanho de fonte",16,true));Slider s=new Slider{Minimum=12,Maximum=28,Value=16,Width=300,HorizontalAlignment=HorizontalAlignment.Left};page.Children.Add(s);CheckBox sound=new CheckBox{Content="Sons",Margin=new Thickness(6)};page.Children.Add(sound);CheckBox metrics=new CheckBox{Content="Exibir métricas",IsChecked=true,Margin=new Thickness(6)};page.Children.Add(metrics);page.Children.Add(B("Salvar",delegate{MessageBox.Show("Configurações aplicadas durante esta sessão.");}));}
 }
